CREATE TABLE t0(id INTEGER PRIMARY KEY, c0 NUMERIC NOT NULL DEFAULT 0, c1 INTEGER COLLATE NOCASE, c2 TEXT COLLATE NOCASE, c3 INT COLLATE NOCASE);
INSERT OR IGNORE INTO t0(c0, c1, c2, c3) VALUES('chi', 'xi', 'alpha', x'');
CREATE TABLE t1(id INTEGER PRIMARY KEY, c0 INT DEFAULT 'd', c1  DEFAULT 'd', c2 REAL, c3 REAL COLLATE NOCASE, c4 TEXT);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, c4) VALUES(x'', x'e19903', x'38af1af8', -4, 10);
INSERT OR IGNORE INTO t1(c0, c1, c2, c3, c4) VALUES(121.954, NULL, 712, 365, -2);
SELECT length('eta'), upper('eta'), lower('eta'), substr('eta', -2, 2), instr('eta', 'alpha'), replace('eta', 'e', 'XY'), trim('eta'), ltrim('eta', 'ab'), hex('eta'), quote('eta'), unicode('eta'), 'eta' LIKE '%é%', 'eta' GLOB '*', char(69, 263), 'eta' || 'alpha', 'eta' < 'alpha', 'eta' = 'alpha' COLLATE NOCASE;
SELECT length('phi'), upper('phi'), lower('phi'), substr('phi', 3, 2), instr('phi', 'kappa'), replace('phi', '', 'XY'), trim('phi'), ltrim('phi', 'ab'), hex('phi'), quote('phi'), unicode('phi'), 'phi' LIKE '%a_', 'phi' GLOB '*', char(90, 568), 'phi' || 'kappa', 'phi' < 'kappa', 'phi' = 'kappa' COLLATE NOCASE;
SELECT length('pi'), upper('pi'), lower('pi'), substr('pi', 3, 0), instr('pi', 'kappa'), replace('pi', '', 'XY'), trim('pi'), ltrim('pi', 'ab'), hex('pi'), quote('pi'), unicode('pi'), 'pi' LIKE '%é%', 'pi' GLOB '?', char(87, 520), 'pi' || 'kappa', 'pi' < 'kappa', 'pi' = 'kappa' COLLATE NOCASE;
SELECT length('upsilon'), upper('upsilon'), lower('upsilon'), substr('upsilon', -2, 1), instr('upsilon', 'sigma'), replace('upsilon', 'e', ''), trim('upsilon'), ltrim('upsilon', 'ab'), hex('upsilon'), quote('upsilon'), unicode('upsilon'), 'upsilon' LIKE '%', 'upsilon' GLOB '*[a-m]*', char(81, 705), 'upsilon' || 'sigma', 'upsilon' < 'sigma', 'upsilon' = 'sigma' COLLATE NOCASE;
SELECT length('gamma'), upper('gamma'), lower('gamma'), substr('gamma', -1, 2), instr('gamma', 'x_y'), replace('gamma', 'a', '_'), trim('gamma'), ltrim('gamma', 'ab'), hex('gamma'), quote('gamma'), unicode('gamma'), 'gamma' LIKE '%a_', 'gamma' GLOB 'a*', char(78, 655), 'gamma' || 'x_y', 'gamma' < 'x_y', 'gamma' = 'x_y' COLLATE NOCASE;
SELECT length('pi'), upper('pi'), lower('pi'), substr('pi', -3, 0), instr('pi', 'alpha'), replace('pi', 'a', '_'), trim('pi'), ltrim('pi', 'ab'), hex('pi'), quote('pi'), unicode('pi'), 'pi' LIKE 'a%', 'pi' GLOB '*', char(86, 775), 'pi' || 'alpha', 'pi' < 'alpha', 'pi' = 'alpha' COLLATE NOCASE;
SELECT length('kappa'), upper('kappa'), lower('kappa'), substr('kappa', -2, 1), instr('kappa', 'omicron'), replace('kappa', 'a', ''), trim('kappa'), ltrim('kappa', 'ab'), hex('kappa'), quote('kappa'), unicode('kappa'), 'kappa' LIKE 'a%', 'kappa' GLOB 'a*', char(79, 445), 'kappa' || 'omicron', 'kappa' < 'omicron', 'kappa' = 'omicron' COLLATE NOCASE;
SELECT printf('%lld', -0.0), round(-0.0, 1), -0.0 * 1.0e15, -0.0 / 0.1, CAST(-0.0 AS TEXT), -0.0 + 0.0;
WITH RECURSIVE f(n, a, b) AS (SELECT 1, 0, 1 UNION ALL SELECT n + 1, b, a + b FROM f WHERE n < 31) SELECT n, a FROM f ORDER BY n DESC LIMIT 5;
WITH RECURSIVE s(x) AS (SELECT 5 UNION ALL SELECT CASE WHEN x % 2 THEN 3 * x + 1 ELSE x / 2 END FROM s WHERE x <> 1) SELECT count(*), max(x), group_concat(x) FROM s;
WITH a(x) AS (VALUES(1),(2),(3)), b(y) AS (SELECT x * x FROM a) SELECT x, y FROM a, b ORDER BY x, y;
